import{_ as o,l as s,o as e,c as i,v as t,p as L,x as l,d as p,i as d,S as n}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"LLDP","description":"","frontmatter":{"title":"LLDP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lldp.md","filePath":"cs/lldp.md","lastUpdated":1789023840000}'),P={name:"cs/lldp.md"};function E(c,a,h,D,T,A){const r=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="lldp" tabindex="-1">LLDP <a class="header-anchor" href="#lldp" aria-label="Permalink to &quot;LLDP&quot;">​</a></h1><div class="epigraph"><p>邻机用 TLV 说出自己的机箱、口名与能力；链路层发现不转发业务，只填一张谁连着谁的图。</p><footer>—— 据 IEEE 802.1AB LLDP；TIA-1057 LLDP-MED 整理</footer></div><p><a href="/cs/lacp">上一课</a>把多口收成逻辑边，运维仍可能插错线。缺口是<strong>邻居发现</strong>：LLDP 在链路上组播自己的 chassis ID、port ID、TTL，对端写入 MIB。本课不把 RSTP 握手写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>ARP 与 ICMP 发现的是三层可达。插错 VLAN、插错 LACP 成员，需要二层「你是谁」。LLDP：目的 MAC 是 01-80-C2-00-00-0E，桥不转发（与某些厂商 CDP 行为对照）。TLV 可带管理地址、IEEE 802.3 能力、MED 给话机供电与 VLAN。TTL 到期则表项消失——邻居离开不必显式再见。</p><p>不要把 LLDP 当认证：未加密，可伪造，只是运维平面。</p><p><span class="marginnote">802.1AB 定义 PDU 与 MIB。CDP 是 Cisco 对照，本课不展开。本课不把 802.1X 证书当 LLDP 的一部分。</span></p><h3 id="发现不是认证" tabindex="-1">发现不是认证 <a class="header-anchor" href="#发现不是认证" aria-label="Permalink to &quot;发现不是认证&quot;">​</a></h3><p>明文 TLV 服务布线对账，可伪造。桥不转发该组播。邻居 TTL 老化，不必显式再见。不改转发拓扑。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每口周期发 LLDP 帧；收则刷新。画：口 → 邻居表（系统名、口描述）。与自协商对照：协商选速率，LLDP 选「人读得懂的名字」。LACP 成员口上 LLDP 仍按物理口报告，便于查捆错。</p>',11)),(e(),L(n,null,{default:l(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E5%91%A8%E6%9C%9F%E7%BB%84%E6%92%AD%20TLV%22%5D%20--%3E%20NB%5B%22%E5%AF%B9%E7%AB%AF%E9%82%BB%E5%B1%85%E8%A1%A8%22%5D%0A%20%20NB%20--%3E%20OPS%5B%22%E5%AF%B9%E8%B4%A6%E5%B8%83%E7%BA%BF%E4%B8%8E%20LAG%22%5D%0A%20%20TX%20--%3E%20EXP%5B%22TTL%20%E5%88%B0%E6%9C%9F%E5%88%A0%E9%99%A4%22%5D%0A"})]),fallback:l(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>生成树 BPDU 也是链路组播，但目的是算树；LLDP 不改转发拓扑。两者可同口并存。交换机架构后课的控制面 CPU 处理这些慢协议，数据面不查 LLDP。</p><p>MED：话机告诉交换机 PoE 与语音 VLAN，仍是 TLV，不是呼叫信令。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 sFlow 采样。RSTP/MSTP 是下一课。后课默认：LLDP 提供一跳身份，不提供可达性证明。</p><p>关闭 LLDP 的安全理由是减少侦察；那是权衡，不是协议缺陷清单。</p><p>上一课留下的缺口在本课收口；「LLDP」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/rstp-mstp">RSTP / MSTP</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLDP 用不可转发组播交换一跳身份。</li><li>TTL 老化邻居；不替代 STP 或 LACP。</li><li>明文、可伪造，服务运维。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.1AB；LLDP-MED。</li></ul>',10))])}const m=o(P,[["render",E]]);export{B as __pageData,m as default};
